#!/bin/sh
# Checks and exports the schematic generated by generate.py.
#
# Needs KiCad 9 (`kicad-cli`). Without it, run it in the official image:
#
#   docker run --rm -u 0 -v "$PWD":/w -w /w kicad/kicad:9.0.9 hardware/kicad/export.sh
#
# 1. ERC: no errors and no warnings
# 2. the netlist KiCad reads is exactly the declared one (tools/check_netlist.py)
# 3. the Pico pins match the firmware and the profile (tools/check_pinmap.py)
# 4. PDF and one SVG per sheet in hardware/exports/kicad/, on white
# 5. no text overlaps another text, a wire or the frame (tools/check_svg_layout.py)
#
# The ERC report and the netlist carry a timestamp: they stay in a temporary
# directory.
set -eu
here=$(cd "$(dirname "$0")" && pwd)
tools="$here/../../tools"
out="$here/../exports/kicad"
tmp=$(mktemp -d)
trap 'rm -rf "$tmp"' EXIT
mkdir -p "$out"
cd "$here"

python3 generate.py --out "$tmp/gen" --nets-json "$tmp/nets.json" >/dev/null
kicad-cli sch erc --severity-all --exit-code-violations -o "$tmp/erc.rpt" tdm-dash.kicad_sch ||
    { cat "$tmp/erc.rpt"; exit 1; }
kicad-cli sch export netlist --format kicadsexpr -o "$tmp/tdm-dash.net" tdm-dash.kicad_sch
python3 "$tools/check_netlist.py" "$tmp/tdm-dash.net" "$tmp/nets.json"
python3 "$tools/check_pinmap.py" "$tmp/tdm-dash.net"

kicad-cli sch export pdf --drawing-sheet tdm-dash.kicad_wks --no-background-color \
    -o "$out/tdm-dash.pdf" tdm-dash.kicad_sch
kicad-cli sch export svg --drawing-sheet tdm-dash.kicad_wks -o "$tmp/svg" tdm-dash.kicad_sch
python3 "$tools/check_svg_layout.py" "$tmp"/svg/*.svg
rm -f "$out"/*.svg
for f in "$tmp"/svg/*.svg; do
    # "tdm-dash-3 Tachometer.svg" -> "3-tachometer.svg", the root sheet -> "0-index.svg"
    name=$(basename "$f" .svg | sed 's/^tdm-dash-\{0,1\}//; s/ /-/g' | tr 'A-Z' 'a-z')
    # drop the export time from the <title>, so unchanged sheets give unchanged
    # files, and plot on white instead of the editor background
    sed -e 's/ date [0-9/]* [0-9:]* </ </' -e 's/#F5F4EF/#FFFFFF/g' "$f" >"$out/${name:-0-index}.svg"
done
ls "$out"
